parameters.jsCode:
// Merge and normalize results from both PubMed and ClinicalTrials.gov sources
const pubmedData = $('PubMed Search').item?.json || {};
const ctgovData = $('ClinicalTrials.gov Search').item?.json || {};

// Extract PubMed IDs
const pmids = pubmedData?.esearchresult?.idlist || [];

// Extract and normalize ClinicalTrials.gov studies
const ctStudies = (ctgovData?.studies || []).map(s => {
  const id = s.protocolSection?.identificationModule;
  const status = s.protocolSection?.statusModule;
  const design = s.protocolSection?.designModule;
  const outcomes = s.protocolSection?.outcomesModule;
  const description = s.protocolSection?.descriptionModule;

  // Detect subspecialty from conditions
  const conditions = (s.protocolSection?.conditionsModule?.conditions || []).join(' ').toLowerCase();
  const subspecialties = [];

  if (conditions.includes('hydrocephalus') || conditions.includes('shunt') || conditions.includes('nph')) {
    subspecialties.push('hydrocephalus');
  }
  if (conditions.includes('spine') || conditions.includes('cervical') || conditions.includes('lumbar') || conditions.includes('stenosis')) {
    subspecialties.push('spine');
  }
  if (conditions.includes('aneurysm') || conditions.includes('avm') || conditions.includes('stroke') || conditions.includes('hemorrhage')) {
    subspecialties.push('vascular');
  }
  if (conditions.includes('glioma') || conditions.includes('meningioma') || conditions.includes('tumor') || conditions.includes('gbm') || conditions.includes('glioblastoma')) {
    subspecialties.push('oncology');
  }
  if (conditions.includes('parkinson') || conditions.includes('dbs') || conditions.includes('epilepsy') || conditions.includes('tremor')) {
    subspecialties.push('functional');
  }
  if (conditions.includes('trauma') || conditions.includes('tbi') || conditions.includes('hematoma')) {
    subspecialties.push('trauma');
  }

  return {
    source: 'clinicaltrials.gov',
    nctId: id?.nctId || '',
    title: id?.officialTitle || id?.briefTitle || '',
    status: status?.overallStatus || '',
    phase: design?.phases?.join(', ') || '',
    enrollment: design?.enrollmentInfo?.count || 0,
    studyType: design?.studyType || '',
    primaryOutcome: outcomes?.primaryOutcomes?.[0]?.measure || '',
    secondaryOutcomes: (outcomes?.secondaryOutcomes || []).map(o => o.measure).slice(0, 3),
    lastUpdate: status?.lastUpdatePostDateStruct?.date || '',
    briefSummary: description?.briefSummary?.substring(0, 500) || '',
    subspecialties: subspecialties.length > 0 ? subspecialties : ['general']
  };
}).filter(s => s.nctId);

// Create unified signal list
const signals = [];

// Add PubMed signals (will be enriched later with abstract fetching)
if (pmids.length > 0) {
  signals.push({
    source: 'pubmed',
    ids: pmids,
    count: pmids.length
  });
}

// Add CT.gov signals
ctStudies.forEach(s => signals.push(s));

return {
  json: {
    pubmed_count: pmids.length,
    ctgov_count: ctStudies.length,
    total_signals: pmids.length + ctStudies.length,
    pubmed_ids: pmids,
    ctgov_studies: ctStudies,
    timestamp: new Date().toISOString(),
    search_date: new Date().toISOString().split('T')[0]
  }
};

// Parse PubMed XML and score abstracts for relevance
const xmlData = $input.first().json.data || '';
const mergedData = $('Merge & Normalize Sources').item.json;

// Simple XML parsing for abstracts
const articles = [];
const articleMatches = xmlData.match(/<PubmedArticle>([\s\S]*?)<\/PubmedArticle>/g) || [];

articleMatches.forEach(articleXml => {
  const pmid = (articleXml.match(/<PMID[^>]*>(\d+)<\/PMID>/) || [])[1] || '';
  const title = (articleXml.match(/<ArticleTitle>([\s\S]*?)<\/ArticleTitle>/) || [])[1] || '';
  const abstractText = (articleXml.match(/<AbstractText[^>]*>([\s\S]*?)<\/AbstractText>/g) || [])
    .map(t => t.replace(/<[^>]+>/g, '')).join(' ');
  const journal = (articleXml.match(/<Title>([\s\S]*?)<\/Title>/) || [])[1] || '';
  const pubYear = (articleXml.match(/<Year>(\d{4})<\/Year>/) || [])[1] || '';
  const pubType = (articleXml.match(/<PublicationType>([\s\S]*?)<\/PublicationType>/g) || [])
    .map(t => t.replace(/<[^>]+>/g, ''));

  // Calculate relevance score
  let score = 0;
  const lowerTitle = title.toLowerCase();
  const lowerAbstract = abstractText.toLowerCase();
  const combined = lowerTitle + ' ' + lowerAbstract;

  // Study design scoring (40 points max)
  if (pubType.some(t => t.toLowerCase().includes('randomized')) || combined.includes('randomized controlled trial') || combined.includes('rct')) {
    score += 40;
  } else if (combined.includes('propensity score') || combined.includes('psm')) {
    score += 30;
  } else if (combined.includes('cohort') || combined.includes('retrospective')) {
    score += 20;
  } else if (combined.includes('meta-analysis') || combined.includes('systematic review')) {
    score += 35;
  }

  // Sample size estimation (20 points max)
  const sampleMatch = combined.match(/(\d+)\s*(patients|subjects|participants)/i);
  if (sampleMatch) {
    const n = parseInt(sampleMatch[1]);
    if (n >= 500) score += 20;
    else if (n >= 200) score += 15;
    else if (n >= 100) score += 10;
    else if (n >= 50) score += 5;
  }

  // Subspecialty detection (20 points max)
  const subspecialties = [];
  if (combined.includes('hydrocephalus') || combined.includes('shunt') || combined.includes('nph')) {
    subspecialties.push('hydrocephalus');
    score += 5;
  }
  if (combined.includes('spine') || combined.includes('cervical') || combined.includes('lumbar') || combined.includes('fusion')) {
    subspecialties.push('spine');
    score += 5;
  }
  if (combined.includes('aneurysm') || combined.includes('avm') || combined.includes('stroke') || combined.includes('hemorrhage')) {
    subspecialties.push('vascular');
    score += 5;
  }
  if (combined.includes('glioma') || combined.includes('meningioma') || combined.includes('tumor') || combined.includes('gbm')) {
    subspecialties.push('oncology');
    score += 5;
  }
  if (combined.includes('parkinson') || combined.includes('dbs') || combined.includes('epilepsy') || combined.includes('tremor')) {
    subspecialties.push('functional');
    score += 5;
  }
  if (combined.includes('trauma') || combined.includes('tbi') || combined.includes('hematoma')) {
    subspecialties.push('trauma');
    score += 5;
  }

  // Journal impact (20 points max) - high-impact neurosurgery journals
  const highImpactJournals = ['journal of neurosurgery', 'neurosurgery', 'lancet neurology', 'jama neurology', 'brain', 'annals of neurology', 'spine', 'world neurosurgery'];
  if (highImpactJournals.some(j => journal.toLowerCase().includes(j))) {
    score += 20;
  }

  articles.push({
    pmid,
    title: title.replace(/<[^>]+>/g, ''),
    abstract: abstractText.substring(0, 1000),
    journal,
    year: pubYear,
    publicationTypes: pubType,
    subspecialties: subspecialties.length > 0 ? subspecialties : ['general'],
    relevanceScore: Math.min(score, 100),
    source: 'pubmed'
  });
});

// Sort by relevance score
articles.sort((a, b) => b.relevanceScore - a.relevanceScore);

return {
  json: {
    ...mergedData,
    scored_articles: articles,
    high_relevance_count: articles.filter(a => a.relevanceScore >= 50).length,
    total_scored: articles.length
  }
};

// Prepare high-relevance signals for NAHN API processing
const data = $input.first().json;
const highRelevanceArticles = data.scored_articles.filter(a => a.relevanceScore >= 50);
const ctgovStudies = data.ctgov_studies || [];

// Combine high-relevance PubMed articles and CT.gov studies
const signals = [];

highRelevanceArticles.forEach(article => {
  signals.push({
    signal_id: `pubmed_${article.pmid}`,
    source: 'pubmed',
    title: article.title,
    abstract: article.abstract,
    journal: article.journal,
    year: article.year,
    subspecialties: article.subspecialties,
    relevance_score: article.relevanceScore,
    pmid: article.pmid,
    study_design: article.publicationTypes.join(', ')
  });
});

ctgovStudies.forEach(study => {
  signals.push({
    signal_id: `ctgov_${study.nctId}`,
    source: 'clinicaltrials.gov',
    title: study.title,
    abstract: study.briefSummary,
    nct_id: study.nctId,
    subspecialties: study.subspecialties,
    enrollment: study.enrollment,
    phase: study.phase,
    primary_outcome: study.primaryOutcome,
    study_design: study.studyType
  });
});

return signals.map(s => ({ json: s }));

