parameters.jsCode:
// Merge results from Deep Research, Snowballing, and Exa Search
const originalSignal = $('Process Each Signal').item.json;
const nahnEval = $('NAHN API Evaluate').item.json;
const deepResearch = $('Deep Research Agent').item?.json || {};
const snowball = $('Backward Snowballing').item?.json || {};
const exaSearch = $('Exa Semantic Search').item?.json || {};

// Combine all findings
const enhancedSignal = {
  // Original signal data
  signal_id: originalSignal.signal_id,
  source: originalSignal.source,
  title: originalSignal.title,
  abstract: originalSignal.abstract,
  pmid: originalSignal.pmid,
  nct_id: originalSignal.nct_id,

  // NAHN evaluation results
  subspecialty: nahnEval.subspecialty,
  relevance_score: nahnEval.relevance_score || originalSignal.relevance_score,
  recommended_methods: nahnEval.recommended_methods || [],
  target_journals: nahnEval.target_journals || [],
  subgroups: nahnEval.subgroups || [],
  spinoff_opportunities: nahnEval.spinoff_opportunities || [],
  network_validation: nahnEval.network_validation || {},

  // Deep Research synthesis
  deep_research: {
    comprehensive_report: deepResearch.report || '',
    citations: deepResearch.citations || [],
    key_findings: deepResearch.key_findings || [],
    methodology_recommendations: deepResearch.methodology_recommendations || [],
    evidence_gaps: deepResearch.evidence_gaps || []
  },

  // Snowballing results
  snowball_expansion: {
    additional_papers: snowball.papers || [],
    total_expanded: snowball.total_papers || 0,
    citation_network: snowball.network || {},
    key_references: snowball.key_references || []
  },

  // Exa semantic search results
  semantic_search: {
    related_studies: exaSearch.related_studies || [],
    methodology_insights: exaSearch.methodology_insights || '',
    gap_analysis: exaSearch.gap_analysis || '',
    search_quality: exaSearch.search_quality || 0
  },

  // Metadata
  processed_at: new Date().toISOString(),
  pipeline_version: '2.0.0',
  enhancement_layers: ['deep_research', 'snowballing', 'semantic_search']
};

// Calculate enhanced priority score
let priorityScore = nahnEval.relevance_score || 50;

// Boost for comprehensive deep research
if (deepResearch.report && deepResearch.report.length > 1000) {
  priorityScore += 10;
}

// Boost for successful snowballing
if (snowball.total_papers > 10) {
  priorityScore += 5;
}

// Boost for strong semantic matches
if (exaSearch.related_studies && exaSearch.related_studies.length > 5) {
  priorityScore += 5;
}

enhancedSignal.enhanced_priority_score = Math.min(priorityScore, 100);

return { json: enhancedSignal };

// Format comprehensive notification with all research layers
const signal = $input.first().json;

// Build rich email HTML
const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 800px; margin: 0 auto;">
  <div style="background: linear-gradient(135deg, #1a365d 0%, #2d5a87 100%); color: white; padding: 20px; border-radius: 8px 8px 0 0;">
    <h1 style="margin: 0;">🧠 NAHN Enhanced Signal Alert</h1>
    <p style="margin: 5px 0 0 0; opacity: 0.9;">Neurosurgical Automated High-impact Network v2.0</p>
  </div>

  <div style="background: #f8fafc; padding: 20px; border: 1px solid #e2e8f0;">
    <h2 style="color: #1a365d; margin-top: 0;">${signal.title}</h2>

    <div style="display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 15px;">
      <span style="background: #3182ce; color: white; padding: 4px 12px; border-radius: 20px; font-size: 12px;">
        ${signal.subspecialty}
      </span>
      <span style="background: ${signal.enhanced_priority_score >= 70 ? '#38a169' : signal.enhanced_priority_score >= 50 ? '#d69e2e' : '#e53e3e'}; color: white; padding: 4px 12px; border-radius: 20px; font-size: 12px;">
        Priority: ${signal.enhanced_priority_score}/100
      </span>
      <span style="background: #805ad5; color: white; padding: 4px 12px; border-radius: 20px; font-size: 12px;">
        ${signal.source}
      </span>
    </div>

    <div style="background: white; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
      <h3 style="color: #2d3748; margin-top: 0;">📊 Recommended Methods</h3>
      <ul style="margin: 0; padding-left: 20px;">
        ${(signal.recommended_methods || []).slice(0, 5).map(m => `<li>${m.method || m}: ${m.rationale || 'Recommended based on study characteristics'}</li>`).join('')}
      </ul>
    </div>

    <div style="background: white; padding: 15px; border-radius: 8px; margin-bottom: 15px;">
      <h3 style="color: #2d3748; margin-top: 0;">📚 Target Journals</h3>
      <ul style="margin: 0; padding-left: 20px;">
        ${(signal.target_journals || []).slice(0, 5).map(j => `<li><strong>${j.name || j}</strong> (IF: ${j.impact_factor || 'N/A'})</li>`).join('')}
      </ul>
    </div>

    ${signal.deep_research?.comprehensive_report ? `
    <div style="background: #edf2f7; padding: 15px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid #3182ce;">
      <h3 style="color: #2d3748; margin-top: 0;">🔬 Deep Research Synthesis</h3>
      <p style="margin: 0; white-space: pre-wrap;">${signal.deep_research.comprehensive_report.substring(0, 1500)}...</p>
      <p style="margin: 10px 0 0 0; font-size: 12px; color: #718096;">Citations: ${signal.deep_research.citations?.length || 0} sources</p>
    </div>
    ` : ''}

    ${signal.snowball_expansion?.total_expanded > 0 ? `
    <div style="background: #faf5ff; padding: 15px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid #805ad5;">
      <h3 style="color: #2d3748; margin-top: 0;">🔗 Snowball Expansion</h3>
      <p style="margin: 0;">Found <strong>${signal.snowball_expansion.total_expanded}</strong> additional related papers through backward snowballing.</p>
      ${signal.snowball_expansion.key_references?.length > 0 ? `
      <p style="margin: 10px 0 0 0;"><strong>Key References:</strong></p>
      <ul style="margin: 5px 0 0 0; padding-left: 20px;">
        ${signal.snowball_expansion.key_references.slice(0, 3).map(r => `<li>${r.title || r}</li>`).join('')}
      </ul>
      ` : ''}
    </div>
    ` : ''}

    ${signal.semantic_search?.gap_analysis ? `
    <div style="background: #fffaf0; padding: 15px; border-radius: 8px; margin-bottom: 15px; border-left: 4px solid #dd6b20;">
      <h3 style="color: #2d3748; margin-top: 0;">🎯 Evidence Gap Analysis</h3>
      <p style="margin: 0;">${signal.semantic_search.gap_analysis}</p>
    </div>
    ` : ''}

    <div style="background: white; padding: 15px; border-radius: 8px;">
      <h3 style="color: #2d3748; margin-top: 0;">👥 Subgroup Opportunities</h3>
      <ul style="margin: 0; padding-left: 20px;">
        ${(signal.subgroups || []).slice(0, 5).map(s => `<li>${s.name || s}: ${s.rationale || ''}</li>`).join('')}
      </ul>
    </div>
  </div>

  <div style="background: #1a365d; color: white; padding: 15px; border-radius: 0 0 8px 8px; text-align: center;">
    <p style="margin: 0; font-size: 12px;">NAHN Enhanced Pipeline v2.0 | Processed: ${signal.processed_at}</p>
    <p style="margin: 5px 0 0 0; font-size: 11px; opacity: 0.8;">Enhancement Layers: ${signal.enhancement_layers?.join(', ') || 'standard'}</p>
  </div>
</div>
`;

// Build Slack blocks
const slackBlocks = [
  {
    type: 'header',
    text: {
      type: 'plain_text',
      text: '🧠 NAHN Enhanced Signal Alert',
      emoji: true
    }
  },
  {
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*${signal.title}*`
    }
  },
  {
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `📍 *Subspecialty:* ${signal.subspecialty} | 📊 *Priority:* ${signal.enhanced_priority_score}/100 | 🔬 *Source:* ${signal.source}`
      }
    ]
  },
  {
    type: 'divider'
  },
  {
    type: 'section',
    fields: [
      {
        type: 'mrkdwn',
        text: `*Recommended Methods:*\n${(signal.recommended_methods || []).slice(0, 3).map(m => `• ${m.method || m}`).join('\n')}`
      },
      {
        type: 'mrkdwn',
        text: `*Target Journals:*\n${(signal.target_journals || []).slice(0, 3).map(j => `• ${j.name || j}`).join('\n')}`
      }
    ]
  }
];

if (signal.deep_research?.key_findings?.length > 0) {
  slackBlocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: `*🔬 Key Findings from Deep Research:*\n${signal.deep_research.key_findings.slice(0, 3).map(f => `• ${f}`).join('\n')}`
    }
  });
}

if (signal.snowball_expansion?.total_expanded > 0) {
  slackBlocks.push({
    type: 'context',
    elements: [
      {
        type: 'mrkdwn',
        text: `🔗 *Snowball Expansion:* Found ${signal.snowball_expansion.total_expanded} additional related papers`
      }
    ]
  });
}

slackBlocks.push({
  type: 'context',
  elements: [
    {
      type: 'mrkdwn',
      text: `_NAHN Enhanced Pipeline v2.0 | ${signal.processed_at}_`
    }
  ]
});

return {
  json: {
    ...signal,
    email_html: emailHtml,
    email_subject: `[NAHN v2] ${signal.subspecialty}: ${signal.title.substring(0, 60)}...`,
    slack_blocks: slackBlocks
  }
};

// Build final notification payloads
const signal = $input.first().json;

return {
  json: {
    email: {
      to: '{{ $env.NOTIFICATION_EMAIL }}',
      subject: signal.email_subject,
      html: signal.email_html
    },
    slack: {
      channel: '{{ $env.SLACK_CHANNEL || "#nahn-alerts" }}',
      blocks: signal.slack_blocks
    },
    signal: signal
  }
};

