// Log API failure for debugging
const error = $input.first().json;
console.error('NAHN API Failure:', JSON.stringify(error));

return {
  json: {
    error: true,
    message: 'NAHN API evaluation failed',
    details: error,
    timestamp: new Date().toISOString()
  }
};

// No results found - log and exit gracefully
return {
  json: {
    status: 'no_results',
    message: 'No new signals found in this search cycle',
    timestamp: new Date().toISOString()
  }
};

// Low relevance - log and skip processing
return {
  json: {
    status: 'low_relevance',
    message: 'No high-relevance signals found in this batch',
    total_scored: $json.total_scored,
    high_relevance_count: $json.high_relevance_count,
    timestamp: new Date().toISOString()
  }
};

// Aggregate daily summary
const allSignals = $items('Store Enhanced Signal').map(item => item.json);

const summary = {
  date: new Date().toISOString().split('T')[0],
  total_signals_processed: allSignals.length,
  by_subspecialty: {},
  by_source: {},
  high_priority_count: 0,
  deep_research_count: 0,
  snowball_expanded_count: 0,
  average_priority_score: 0
};

let totalScore = 0;

allSignals.forEach(s => {
  // Count by subspecialty
  const subspec = s.signal?.subspecialty || 'unknown';
  summary.by_subspecialty[subspec] = (summary.by_subspecialty[subspec] || 0) + 1;

  // Count by source
  const source = s.signal?.source || 'unknown';
  summary.by_source[source] = (summary.by_source[source] || 0) + 1;

  // Count high priority
  if (s.signal?.enhanced_priority_score >= 70) {
    summary.high_priority_count++;
  }

  // Count deep research
  if (s.signal?.deep_research?.comprehensive_report) {
    summary.deep_research_count++;
  }

  // Count snowball expanded
  if (s.signal?.snowball_expansion?.total_expanded > 0) {
    summary.snowball_expanded_count++;
  }

  totalScore += s.signal?.enhanced_priority_score || 0;
});

summary.average_priority_score = allSignals.length > 0 ? Math.round(totalScore / allSignals.length) : 0;

return { json: summary };

// Test signal for iNPH (Idiopathic Normal Pressure Hydrocephalus)
return {
  json: {
    signal_id: 'test_inph_001',
    source: 'test',
    title: 'Comparison of Ventriculoperitoneal Shunt vs Endoscopic Third Ventriculostomy for iNPH: A Randomized Controlled Trial',
    abstract: 'Background: Idiopathic normal pressure hydrocephalus (iNPH) is a treatable cause of dementia in elderly patients. The optimal surgical treatment remains debated. Methods: We conducted a multicenter RCT comparing VP shunt (n=150) vs ETV (n=148) in patients with probable iNPH. Primary outcome was improvement in gait at 12 months. Results: VP shunt showed superior outcomes (72% vs 58% improvement, p=0.02). Complications were similar between groups. Conclusion: VP shunt remains the preferred treatment for iNPH.',
    subspecialties: ['hydrocephalus'],
    study_design: 'Randomized Controlled Trial',
    enrollment: 298
  }
};

// Test signal for Spine Surgery
return {
  json: {
    signal_id: 'test_spine_001',
    source: 'test',
    title: 'Minimally Invasive vs Open Lumbar Fusion for Degenerative Spondylolisthesis: 5-Year Outcomes from a Propensity-Matched Cohort',
    abstract: 'Purpose: To compare long-term outcomes of minimally invasive transforaminal lumbar interbody fusion (MIS-TLIF) versus open TLIF for degenerative spondylolisthesis. Methods: Propensity score matching was used to compare 245 MIS-TLIF and 245 open TLIF patients. Outcomes included ODI, VAS, fusion rates, and complications at 5 years. Results: MIS-TLIF showed equivalent fusion rates (94% vs 92%) with reduced blood loss and shorter hospital stay. Long-term functional outcomes were similar. Conclusions: MIS-TLIF offers comparable efficacy with reduced perioperative morbidity.',
